import numpy as np

def feature(item, bins, capacity):
    """Best-fit residual scaled by the bin's own fill: -(room after placing)/capacity * (used/capacity)."""
    room_after = bins - item
    used = capacity - bins
    return -(room_after / capacity) * (used / capacity)

