import numpy as np

def feature(item, bins, capacity):
    """Negative normalised candidate index: oldest open bin 0, brand-new bin -1, linear in between."""
    k = len(bins)
    idx = np.arange(k, dtype=float)
    return -(idx / max(k - 1, 1))

import numpy as np

def feature(item, bins, capacity):
    """Gate on large items: +1 for usable post-placement residue (>=0.30 or <=0.02), -1 otherwise, with the empty bin penalised when an open bin is usable."""
    b = np.asarray(bins, dtype=float) / capacity
    x = float(item) / capacity
    post = np.clip(b - x, 0.0, 1.0)
    usable = (post >= 0.30) | (post <= 0.02)
    val = np.where(usable, 1.0, -1.0)
    if x < 0.25:
        return np.zeros_like(b)
    if usable[:-1].any():
        val[-1] -= 1.0
    return np.clip(val, -1.0, 1.0)

import numpy as np

def feature(item, bins, capacity):
    """Three smoothly size-gated residue-basin columns: small (target 0.10, width 0.12), mid (0.28, 0.18), large (0.00, 0.08)."""
    cap = float(capacity) if capacity else 1.0
    b = np.asarray(bins, dtype=float) / cap
    x = float(item) / cap
    post = np.clip(b - x, 0.0, 1.0)

    def gate(z):
        return 1.0 / (1.0 + np.exp(-np.clip(z, -60.0, 60.0)))

    g_small = gate((0.22 - x) / 0.05)
    g_large = gate((x - 0.42) / 0.05)
    g_mid = np.clip(1.0 - g_small - g_large, 0.0, 1.0)

    def basin(t, s):
        u = (post - t) / s
        return -u * u / (1.0 + u * u)

    return np.stack([g_small * basin(0.10, 0.12),
                     g_mid * basin(0.28, 0.18),
                     g_large * basin(0.00, 0.08)], axis=1)
